def transform(grid):
    # Stack the three foreground layers: color 5 has priority over 4, then 2.
    out = []
    for r in range(3):
        row = []
        for c in range(6):
            row.append(next((grid[base + r][c] for base in (0, 3, 6) if grid[base + r][c] != 0), 0))
        out.append(row)
    return out

